"""Validation of the SQL generated by the LLM, before it runs.

The LLM's SQL is treated as untrusted input. Its syntax tree is inspected with sqlglot instead of
the raw text: a regular expression can be dodged with comments, casing or functions, and it would
also block harmless columns such as `deleted_at`. Only a single read query over the allowed tables
is accepted.

This is the first line of defense. The second one lives in db.py: SQLite itself enforces the same
rules, so a difference between how sqlglot and SQLite read a query does not open any door.
"""

from __future__ import annotations

import sqlglot
from sqlglot import exp
from sqlglot.errors import SqlglotError

from pedidos.errors import UnsafeQueryError

ALLOWED_TABLES = frozenset({"pedidos", "ventas_mes_pais", "top_clientes"})

# SQLite functions that add nothing to an analytical query and do open risks:
# loading native code, reading or writing files, or exhausting memory.
DENIED_FUNCTIONS = frozenset(
    {"load_extension", "readfile", "writefile", "edit", "fts3_tokenizer", "randomblob", "zeroblob"}
)
MAX_SQL_LENGTH = 4_000

# Nodes that can never appear inside a read query
_FORBIDDEN_NODES = (
    exp.Insert,
    exp.Update,
    exp.Delete,
    exp.Merge,
    exp.Create,
    exp.Drop,
    exp.Alter,
    exp.Command,
    exp.Into,
)


def validate_sql(sql: str) -> None:
    """Raises UnsafeQueryError, with a clear reason, if the SQL is not safe to run."""
    if not sql or not sql.strip():
        raise UnsafeQueryError("La consulta está vacía.")
    if len(sql) > MAX_SQL_LENGTH:
        raise UnsafeQueryError(f"La consulta es demasiado larga (máximo {MAX_SQL_LENGTH} caracteres).")
    try:
        statements = [statement for statement in sqlglot.parse(sql, read="sqlite") if statement]
    except SqlglotError as error:
        raise UnsafeQueryError("La consulta no es SQL válido.") from error

    if not statements:
        raise UnsafeQueryError("La consulta está vacía.")
    if len(statements) > 1:
        raise UnsafeQueryError("Solo se permite una sentencia SQL.")
    tree = statements[0]
    if not isinstance(tree, exp.Query):
        raise UnsafeQueryError("Solo se permiten consultas de lectura (SELECT).")

    forbidden = tree.find(*_FORBIDDEN_NODES)
    if forbidden is not None:
        raise UnsafeQueryError(f"La consulta contiene una operación no permitida ({forbidden.key.upper()}).")
    if any(with_.args.get("recursive") for with_ in tree.find_all(exp.With)):
        raise UnsafeQueryError("No se permiten CTE recursivos.")
    _check_tables(tree)
    _check_functions(tree)


def _check_tables(tree: exp.Expression) -> None:
    cte_names = {cte.alias_or_name.lower() for cte in tree.find_all(exp.CTE)}
    for table in tree.find_all(exp.Table):
        if not isinstance(table.this, exp.Identifier):
            raise UnsafeQueryError("No se permiten funciones en el FROM, solo tablas.")
        name, schema = table.name.lower(), table.db.lower()
        if table.catalog or schema not in ("", "main"):
            raise UnsafeQueryError(f"Solo se puede consultar la base de datos principal ({table.sql()}).")
        if not schema and name in cte_names:
            continue  # a reference to a CTE of the query itself (its body is checked too)
        if name not in ALLOWED_TABLES:
            allowed = ", ".join(sorted(ALLOWED_TABLES))
            raise UnsafeQueryError(f"Tabla no permitida: {table.name}. Solo se puede consultar: {allowed}.")


def _check_functions(tree: exp.Expression) -> None:
    for function in tree.find_all(exp.Func):
        name = function.name if isinstance(function, exp.Anonymous) else function.sql_name()
        if name.lower() in DENIED_FUNCTIONS:
            raise UnsafeQueryError(f"Función no permitida: {name.lower()}.")
